def state_abstraction(grid, goal):
    # Define the abstraction function
    def abstract_state(state):
        if state == goal:
            return 0  # Goal state
        elif state in get_neighbors(goal, grid):
            return 1  # States adjacent to the goal
        else:
            for i in range(2, len(grid) + len(grid[0]) - 1):
                if state in get_neighbors_at_distance(i, goal, grid):
                    return i  # States at distance i from the goal

    # Get neighbors of a state
    def get_neighbors(state, grid):
        x = state // len(grid[0])
        y = state % len(grid[0])
        neighbors = []
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] != "X":
                neighbors.append(nx * len(grid[0]) + ny)
        return neighbors

    # Get states at a certain distance from the goal
    def get_neighbors_at_distance(distance, state, grid):
        x = state // len(grid[0])
        y = state % len(grid[0])
        visited = set()
        queue = [(x, y, 0)]
        result = []
        while queue:
            nx, ny, nd = queue.pop(0)
            if (nx, ny) not in visited and grid[nx][ny] != "X":
                visited.add((nx, ny))
                if nd == distance:
                    result.append(nx * len(grid[0]) + ny)
                elif nd < distance:
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        queue.append((nx + dx, ny + dy, nd + 1))
        return result

    abstraction = []
    for i in range(len(grid)):
        row_abstraction = []
        for j in range(len(grid[0])):
            if grid[i][j] != "X":
                state = i * len(grid[0]) + j
                abstracted_state = abstract_state(state)
                row_abstraction.append(abstracted_state)
            else:
                row_abstraction.append(-1)  # -1 represents an obstacle or out of bounds
        abstraction.append(row_abstraction)

    return abstraction


