def group_states(grid):
    # Define the goal state
    goal = 52

    # Initialize a set to store states that are directly connected to the goal
    goal_connected = set()

    # Find all states that are adjacent to the goal
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == goal:
                # Check all four directions (up, down, left, right)
                for x, y in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    new_i, new_j = i + x, j + y
                    if 0 <= new_i < len(grid) and 0 <= new_j < len(grid[new_i]):
                        # Check if the adjacent cell is not an obstacle ("X")
                        if grid[new_i][new_j] != "X":
                            goal_connected.add(grid[new_i][new_j])

    # Initialize a list to store groups of states
    groups = []

    # Group all other states based on their connectivity
    visited = set()
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != "X" and grid[i][j] not in visited:
                group = []
                stack = [grid[i][j]]
                while stack:
                    state = stack.pop()
                    if state not in visited:
                        visited.add(state)
                        group.append(state)
                        # Find all adjacent states
                        for k in range(len(grid)):
                            for col, val in enumerate(grid[k]):
                                if val == state:
                                    # Check all four directions (up, down, left, right)
                                    for x, y in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                        new_i, new_j = k + x, col + y
                                        if 0 <= new_i < len(grid) and 0 <= new_j < len(grid[new_i]):
                                            # Check if the adjacent cell is not an obstacle ("X") and has not been visited yet
                                            if grid[new_i][new_j] != "X" and grid[new_i][new_j] not in visited:
                                                stack.append(grid[new_i][new_j])
                groups.append(group)

    # Add the goal-connected states as a separate group
    groups.append(list(goal_connected))

    return groups


